mapper.select:
SELECT * FROM PB_ASSESS_MONTH_RESULT
WHERE ORG_IDENTITY = #{orgIdentity} AND MODULE_CODE = #{moduleCode}
  AND ASSESS_YEAR = #{year} AND ASSESS_MONTH = #{month}
ORDER BY ASSESS_ORG_ID FOR UPDATE

SELECT DEPT_ID, DEPT_NAME FROM PB_ASSESS_RESULT_DEPT
WHERE ORG_IDENTITY = #{orgIdentity} AND RESULT_ID = #{resultId}
ORDER BY DEPT_ID

SELECT CATEGORY_CODE, MODULE_CODE, MODULE_NAME FROM (
    SELECT CATEGORY_CODE, MODULE_CODE, MODULE_NAME,
        ROW_NUMBER() OVER (PARTITION BY MODULE_CODE ORDER BY LAST_UPDATE_DATE DESC, ID DESC) RN
    FROM PB_ASSESS_MONTH_RESULT WHERE ORG_IDENTITY = #{orgIdentity}
) WHERE RN = 1 ORDER BY CATEGORY_CODE, MODULE_CODE

SELECT DEPT_ID, DEPT_NAME FROM (
    SELECT DEPT_ID, DEPT_NAME,
        ROW_NUMBER() OVER (PARTITION BY DEPT_ID ORDER BY LAST_UPDATE_DATE DESC, ID DESC) RN
    FROM PB_ASSESS_RESULT_DEPT
    WHERE ORG_IDENTITY = #{orgIdentity}
) WHERE RN = 1 ORDER BY DEPT_NAME, DEPT_ID

mapper.sql:
R.ORG_IDENTITY = #{orgIdentity} AND R.ASSESS_YEAR = #{year} AND R.ASSESS_MONTH = #{month}

    AND EXISTS (SELECT 1 FROM PB_ASSESS_RESULT_DEPT D
        WHERE D.ORG_IDENTITY = R.ORG_IDENTITY AND D.RESULT_ID = R.ID AND D.DEPT_ID = #{departmentId})

AND R.CATEGORY_CODE = #{categoryCode}
AND R.MODULE_CODE = #{moduleCode}
